"""Generate MonsterCN/Data/Conway.lean from co0_data.json, co0_labels.json, co0_witness.json."""
import json

D = json.load(open('co0_data.json'))
L = json.load(open('co0_labels.json'))
W = json.load(open('co0_witness.json'))
names = D['names']

def Lx(xs):
    return '[' + ', '.join(str(x) for x in xs) + ']'

def Sx(xs):
    return '[' + ', '.join('"' + x.replace('\\', '\\\\').replace('"', '\\"') + '"' for x in xs) + ']'

out = ['''/-
# Data for Co0 = 2.Co1 and Conway moonshine (AUTO-GENERATED by `data/gen_co0_lean.py`)

Sources: GAP Character Table Library 1.3.11, `ctoconja.tbl`, table `"2.Co1"` (classes, orders,
centralizer orders, power maps). Faithful characters are taken from `ARC("Co1","projectives",…)`
(value on the first preimage, negated on the second, 0 on classes with one preimage), and `χ₂₇₆`
is pulled back from `"Co1"`. Group labels are copied verbatim (plain-ASCII form) from
Duncan–Mack-Crane, *The moonshine module for Conway's group*, Forum Math. Sigma 3 (2015),
Table A.1.
-/
namespace MonsterCN.Conway
''']
out.append('def coNames : List String := ' + Sx(names))
out.append('def coOrd : List Nat := ' + Lx(D['orders']))
out.append('def coCent : List Nat := ' + Lx(D['cent']))
primes = sorted(int(p) for p in D['pmaps'])
out.append('def coPrimes : List Nat := ' + Lx(primes))
out.append('def coPmap : Nat → List Nat')
for p in primes:
    out.append('  | %d => %s' % (p, Lx(D['pmaps'][str(p)])))
out.append('  | _ => []')
out.append('def coChi24 : List Int := ' + Lx(D['chi24']))
out.append('def coChi276 : List Int := ' + Lx(D['chi276']))
out.append('def coChi2024 : List Int := ' + Lx(L['chi2024']))
out.append('/-- Duncan–Mack-Crane Table A.1 group label of each class (plain ASCII). -/')
out.append('def dmcLabel : List String := ' + Sx(L['lab']))
out.append('/-- Witness permutations `(c, d, π)` with `π c = d`. -/')
out.append('def coWitnesses : List (Nat × Nat × List Nat) := [\n' +
           ',\n'.join('  (%d, %d, %s)' % (w['c'], w['d'], Lx(w['perm'])) for w in W) + ']')
out.append('end MonsterCN.Conway\n')
open('../MonsterCN/Data/Conway.lean', 'w', encoding='utf8').write('\n'.join(out))
print('written; witnesses:', [(names[w['c']], names[w['d']]) for w in W])
